<script>let mood="🙂",note="";let entries=[];function save(){if(note.trim()){entries=[{mood,note,date:new Date().toLocaleDateString()},...entries];note=""}}</script><svelte:head><title>Mood Notes</title></svelte:head><main><h1>Mood Notes</h1><div class="moods">{#each ["😄","🙂","😐","😔"] as m}<button class:active={mood===m} on:click={()=>mood=m}>{m}</button>{/each}</div><textarea bind:value={note} placeholder="What is on your mind?"></textarea><button class="save" on:click={save}>Save note</button>{#each entries as e}<article><b>{e.mood} {e.date}</b><p>{e.note}</p></article>{/each}</main><style>:global(body){margin:0;background:#f4f1eb;font-family:system-ui;color:#27231d}main{max-width:620px;margin:60px auto;padding:24px}.moods{display:flex;gap:8px}.moods button{font-size:26px;background:white;border:1px solid #ddd;border-radius:14px;padding:10px}.active{outline:3px solid #7c3aed}textarea{width:100%;height:110px;box-sizing:border-box;margin:18px 0;padding:16px;border:0;border-radius:16px}.save{background:#7c3aed;color:white;border:0;padding:13px 20px;border-radius:12px}article{background:white;padding:18px;border-radius:16px;margin-top:12px}</style>